H.background();
const w = H.W, h = H.H;
const b = Math.min(5, Math.max(2, P.b));
const M = Math.max(1, P.M), N = Math.max(1, P.N);
const lm = Math.log(M) / Math.log(b);
const ln = Math.log(N) / Math.log(b);
const lmn = lm + ln;
const baseY = h * 0.5;
const x0 = 70, span = w - 160;
const maxL = Math.max(lmn, 1) * 1.15;
const px = u => x0 + (u / maxL) * span;
H.line(x0, baseY, x0 + span, baseY, { color: H.colors.axis, width: 2 });
for (let k = 0; k <= Math.ceil(maxL); k++) {
  H.line(px(k), baseY - 5, px(k), baseY + 5, { color: H.colors.grid, width: 1 });
  H.text(String(k), px(k) - 3, baseY + 22, { color: H.colors.sub, size: 11 });
}
const grow = 0.5 + 0.5 * Math.sin(t * 0.8);
H.rect(x0, baseY - 40, px(lm) - x0, 22, { fill: H.colors.accent, radius: 4 });
H.rect(px(lm), baseY - 40, (px(lm + ln) - px(lm)) * grow, 22, { fill: H.colors.accent2, radius: 4 });
H.text("log M = " + lm.toFixed(2), x0 + 6, baseY - 24, { color: H.colors.ink, size: 12 });
H.text("+ log N", px(lm) + 6, baseY - 24, { color: H.colors.ink, size: 12 });
H.circle(px(lmn), baseY, 6 + 1.5 * Math.sin(t * 3), { fill: H.colors.warn });
H.text("log(MN) = " + lmn.toFixed(2), px(lmn) - 30, baseY + 44, { color: H.colors.good, size: 13 });
H.text("Log laws: multiply -> add exponents", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("log_" + b.toFixed(0) + "(" + M.toFixed(0) + "*" + N.toFixed(0) + ") = log " + M.toFixed(0) + " + log " + N.toFixed(0) + " = " + lm.toFixed(2) + " + " + ln.toFixed(2) + " = " + lmn.toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
